// ConfigToEnvVar converts Config to environment variable key-value pairs.
func ConfigToEnvVar(v *Config) map[string]string {
	if v == nil {
		return nil
	}
	result := make(map[string]string)
	result["PROTO_LIBS_HTTPSERVER_CONFIG_HTTP_LISTEN"] = v.HttpListen
	result["PROTO_LIBS_HTTPSERVER_CONFIG_HTTPS_LISTEN"] = v.HttpsListen
	if v.TlsCert != nil {
		for k, val := range x509.X509CertPairToEnvVar(v.TlsCert) {
			result[k] = val
		}
	}
	result["PROTO_LIBS_HTTPSERVER_CONFIG_SERVER_MODE"] = ServerModeToString(v.ServerMode)
	result["PROTO_LIBS_HTTPSERVER_CONFIG_FQDN"] = v.Fqdn
	result["PROTO_LIBS_HTTPSERVER_CONFIG_LETS_ENCRYPT_EMAIL"] = v.LetsEncryptEmail
	return result
}

// ConfigFromEnvVar creates Config from environment variable key-value pairs.
func ConfigFromEnvVar(env map[string]string) (*Config, error) {
	result := &Config{}
	if val, ok := env["PROTO_LIBS_HTTPSERVER_CONFIG_HTTP_LISTEN"]; ok && val != "" {
		result.HttpListen = val
	}
	if val, ok := env["PROTO_LIBS_HTTPSERVER_CONFIG_HTTPS_LISTEN"]; ok && val != "" {
		result.HttpsListen = val
	}
	if sub, err := x509.X509CertPairFromEnvVar(env); err != nil {
		return nil, err
	} else if sub != nil {
		result.TlsCert = sub
	}
	if val, ok := env["PROTO_LIBS_HTTPSERVER_CONFIG_SERVER_MODE"]; ok && val != "" {
		parsed, err := ParseServerMode(val)
		if err != nil {
			return nil, err
		}
		result.ServerMode = parsed
	}
	if val, ok := env["PROTO_LIBS_HTTPSERVER_CONFIG_FQDN"]; ok && val != "" {
		result.Fqdn = val
	}
	if val, ok := env["PROTO_LIBS_HTTPSERVER_CONFIG_LETS_ENCRYPT_EMAIL"]; ok && val != "" {
		result.LetsEncryptEmail = val
	}
	return result, nil
}

