// ============================================================
// Validation Helpers
// ============================================================
// ValidateConfig validates all fields in Config according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateConfig(m *Config) error {
	if m == nil {
		return nil
	}

	// Validate HttpListen (assert_listen_addr)
	if m.HttpListen != "" {
		if err := utils.ValidateAssertListenAddr(m.HttpListen); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field HttpListen listen address validation failed")
		}
	}

	// Validate HttpsListen (assert_listen_addr)
	if m.HttpsListen != "" {
		if err := utils.ValidateAssertListenAddr(m.HttpsListen); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field HttpsListen listen address validation failed")
		}
	}

	// Validate Fqdn (assert_fqdn)
	if m.Fqdn != "" {
		if err := utils.ValidateAssertFQDN(m.Fqdn); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Fqdn FQDN validation failed")
		}
	}

	// Validate LetsEncryptEmail (assert_email)
	if m.LetsEncryptEmail != "" {
		if err := utils.ValidateAssertEmail(m.LetsEncryptEmail); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field LetsEncryptEmail email validation failed")
		}
	}

	// Validate HttpListen (default max size: 32768 bytes)
	if len(m.HttpListen) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field HttpListen exceeds max size of 32768 bytes, got: %d", len(m.HttpListen))
	}

	// Validate HttpsListen (default max size: 32768 bytes)
	if len(m.HttpsListen) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field HttpsListen exceeds max size of 32768 bytes, got: %d", len(m.HttpsListen))
	}

	// Validate Fqdn (default max size: 32768 bytes)
	if len(m.Fqdn) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Fqdn exceeds max size of 32768 bytes, got: %d", len(m.Fqdn))
	}

	// Validate LetsEncryptEmail (default max size: 32768 bytes)
	if len(m.LetsEncryptEmail) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field LetsEncryptEmail exceeds max size of 32768 bytes, got: %d", len(m.LetsEncryptEmail))
	}

	return nil
}

// ValidateState validates all fields in State according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateState(m *State) error {
	if m == nil {
		return nil
	}

	// Validate LastUpdated (assert_gt: 0)
	if m.LastUpdated <= 0 {
		return protoerrors.NewErrMissingInvalidData(nil, "field LastUpdated must be > 0, got: %v", m.LastUpdated)
	}
	return nil
}

// ValidateCertState validates all fields in CertState according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateCertState(m *CertState) error {
	if m == nil {
		return nil
	}

	// Validate ModTime (assert_ge: 0)
	if m.ModTime < 0 {
		return protoerrors.NewErrMissingInvalidData(nil, "field ModTime must be >= 0, got: %v", m.ModTime)
	}
	// Validate Value (default max size: 32768 bytes)
	if len(m.Value) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Value exceeds max size of 32768 bytes, got: %d", len(m.Value))
	}

	return nil
}

// ValidateStaticFilePath validates all fields in StaticFilePath according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateStaticFilePath(m *StaticFilePath) error {
	if m == nil {
		return nil
	}

	// Validate UrlPath (assert_required)
	if m.UrlPath == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field UrlPath is required")
	}

	// Validate Directory (assert_required)
	if m.Directory == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field Directory is required")
	}

	// Validate UrlPath (default max size: 32768 bytes)
	if len(m.UrlPath) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field UrlPath exceeds max size of 32768 bytes, got: %d", len(m.UrlPath))
	}

	// Validate Directory (default max size: 32768 bytes)
	if len(m.Directory) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Directory exceeds max size of 32768 bytes, got: %d", len(m.Directory))
	}

	return nil
}

// ValidateHealthCheckResponse validates all fields in HealthCheckResponse according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateHealthCheckResponse(m *HealthCheckResponse) error {
	if m == nil {
		return nil
	}

	// Validate Status (default max size: 32768 bytes)
	if len(m.Status) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Status exceeds max size of 32768 bytes, got: %d", len(m.Status))
	}

	return nil
}

