// ============================================================
// Merge: Config
// ============================================================
// MergeConfig fills zero-valued fields in dst from src.
func MergeConfig(dst, src *Config) {
	if dst.HttpListen == "" {
		dst.HttpListen = src.HttpListen
	}
	if dst.HttpsListen == "" {
		dst.HttpsListen = src.HttpsListen
	}
	if dst.TlsCert == nil {
		dst.TlsCert = src.TlsCert
	}
	if dst.ServerMode == 0 {
		dst.ServerMode = src.ServerMode
	}
	if dst.Fqdn == "" {
		dst.Fqdn = src.Fqdn
	}
	if dst.LetsEncryptEmail == "" {
		dst.LetsEncryptEmail = src.LetsEncryptEmail
	}
	if len(dst.StaticFilePaths) == 0 {
		dst.StaticFilePaths = src.StaticFilePaths
	}
}

// ============================================================
// Merge: State
// ============================================================
// MergeState fills zero-valued fields in dst from src.
func MergeState(dst, src *State) {
	if dst.LastUpdated == 0 {
		dst.LastUpdated = src.LastUpdated
	}
	if dst.Cert == nil {
		dst.Cert = src.Cert
	} else if src.Cert != nil {
		MergeCertState(dst.Cert, src.Cert)
	}
}

// ============================================================
// Merge: CertState
// ============================================================
// MergeCertState fills zero-valued fields in dst from src.
func MergeCertState(dst, src *CertState) {
	if !dst.IsDir {
		dst.IsDir = src.IsDir
	}
	if dst.ModTime == 0 {
		dst.ModTime = src.ModTime
	}
	if len(dst.Value) == 0 {
		dst.Value = src.Value
	}
}

// ============================================================
// Merge: StaticFilePath
// ============================================================
// MergeStaticFilePath fills zero-valued fields in dst from src.
func MergeStaticFilePath(dst, src *StaticFilePath) {
	if dst.UrlPath == "" {
		dst.UrlPath = src.UrlPath
	}
	if dst.Directory == "" {
		dst.Directory = src.Directory
	}
}

// ============================================================
// Merge: HealthCheckResponse
// ============================================================
// MergeHealthCheckResponse fills zero-valued fields in dst from src.
func MergeHealthCheckResponse(dst, src *HealthCheckResponse) {
	if dst.Status == "" {
		dst.Status = src.Status
	}
	if dst.Time == 0 {
		dst.Time = src.Time
	}
}
